function validate([sentence, rows, cols]) {
  if (!Array.isArray(sentence) || sentence.length < 1 || sentence.length > 100) return 'sentence needs 1 to 100 words.';
  if (sentence.some(w => typeof w !== 'string' || !/^[a-z]{1,10}$/.test(w))) return 'Each word has 1 to 10 lowercase English letters.';
  if (!Number.isInteger(rows) || rows < 1 || rows > 20000) return 'rows is between 1 and 20000.';
  if (!Number.isInteger(cols) || cols < 1 || cols > 20000) return 'cols is between 1 and 20000.';
  return null;
}

