function wordsTyping(sentence, rows, cols) {
  const text = sentence.join(' ') + ' ';
  const length = text.length;
  let typed = 0;

  for (let row = 0; row < rows; row++) {
    typed += cols;
    if (text[typed % length] === ' ') {
      typed++;
    } else {
      while (typed > 0 && text[(typed - 1) % length] !== ' ') {
        typed--;
      }
    }
  }
  return Math.floor(typed / length);
}

