function wordsTyping(sentence, rows, cols) {
  // Place words one at a time; a row's contents depend only on its first word, so cache that.
  const n = sentence.length;
  const wordsInRow = new Map();
  let word = 0, placed = 0;
  for (let r = 0; r < rows; r++) {
    if (!wordsInRow.has(word)) {
      let used = 0, count = 0;
      for (;;) {
        const len = sentence[(word + count) % n].length;
        const need = count === 0 ? len : used + 1 + len;
        if (need > cols) break;
        used = need;
        count++;
      }
      wordsInRow.set(word, count);
    }
    const count = wordsInRow.get(word);
    placed += count;
    word = (word + count) % n;
  }
  return Math.floor(placed / n);
}

