function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let w = '';
    for (let i = 0; i < len; i++) w += letters[Math.floor(rand() * 26)];
    return w;
  };
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 4);
    const sentence = Array.from({ length: n }, () => word(5));
    return [sentence, 1 + Math.floor(rand() * 8), 1 + Math.floor(rand() * 15)];
  }
  const n = 1 + Math.floor(rand() * 100);
  const maxLen = 1 + Math.floor(rand() * 10);
  const sentence = Array.from({ length: n }, () => word(maxLen));
  const rows = 1 + Math.floor(rand() * 20000);
  const cols = rand() < 0.2 ? 1 + Math.floor(rand() * 12) : 1 + Math.floor(rand() * 20000);
  return [sentence, rows, cols];
}
